From f6a9afe6f2b661839ff34d8bb49599102c2eb0d3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:39:59 +0100
Subject: [PATCH] klipper: add an option to run action commands without a shell

Action commands always ran through /bin/sh, relying on quoting to keep
the clipboard text safe. A per-command checkbox now runs them directly
with each inserted text as one argument, and the hint suggests "--".

BUG: 527863
---
 klipper/clipcommandprocess.cpp | 12 +++++++++++-
 klipper/editcommanddialog.cpp  | 15 +++++++++++++--
 klipper/editcommanddialog.h    |  2 ++
 klipper/urlgrabber.cpp         | 13 ++++++++-----
 klipper/urlgrabber.h           |  2 ++
 5 files changed, 36 insertions(+), 8 deletions(-)

diff --git a/klipper/clipcommandprocess.cpp b/klipper/clipcommandprocess.cpp
index aeaf82f8d2..7f35c4bcce 100644
--- a/klipper/clipcommandprocess.cpp
+++ b/klipper/clipcommandprocess.cpp
@@ -9,6 +9,7 @@
 #include <QMimeData>

 #include <KMacroExpander>
+#include <KShell>

 #include "historyitem.h"
 #include "historymodel.h"
@@ -39,7 +40,16 @@ ClipCommandProcess::ClipCommandProcess(const ClipAction &action, const ClipComma
     }

     setOutputChannelMode(OnlyStdoutChannel);
-    setShellCommand(KMacroExpander::expandMacrosShellQuote(command.command, map).trimmed());
+    if (command.useShell) {
+        setShellCommand(KMacroExpander::expandMacrosShellQuote(command.command, map).trimmed());
+    } else {
+        // Expand each argument on its own, so that an inserted text is always exactly one argument
+        QStringList args = KShell::splitArgs(command.command, KShell::TildeExpand);
+        for (QString &arg : args) {
+            arg = KMacroExpander::expandMacros(arg, map);
+        }
+        setProgram(args);
+    }

     connect(this, SIGNAL(finished(int, QProcess::ExitStatus)), SLOT(slotFinished(int, QProcess::ExitStatus)));
     if (command.output != ClipCommand::IGNORE) {
diff --git a/klipper/editcommanddialog.cpp b/klipper/editcommanddialog.cpp
index 58d13237fe..62aeb8fcfd 100644
--- a/klipper/editcommanddialog.cpp
+++ b/klipper/editcommanddialog.cpp
@@ -6,6 +6,7 @@
 #include "editcommanddialog.h"

 #include <QButtonGroup>
+#include <QCheckBox>
 #include <QDialogButtonBox>
 #include <QFormLayout>
 #include <QLabel>
@@ -73,10 +74,18 @@ EditCommandDialog::EditCommandDialog(const ClipCommand &command, QWidget *parent
                                                         "A <b>&#37;s</b> in the command will be replaced by the "
                                                         "complete clipboard contents. <b>&#37;0</b> through "
                                                         "<b>&#37;9</b> will be replaced by the corresponding "
-                                                        "captured texts from the match pattern."),
+                                                        "captured texts from the match pattern. Put <b>--</b> "
+                                                        "before them if the command accepts it, so that a text "
+                                                        "starting with a dash is not read as an option."),
                                                  optionsWidget);
     optionsLayout->addRow(QString(), hint);

+    m_shellCheck = new QCheckBox(i18n("Run the command in a shell"), optionsWidget);
+    optionsLayout->addRow(QString(), m_shellCheck);
+    optionsLayout->addRow(
+        QString(),
+        ConfigDialog::createHintLabel(i18n("Allows pipes and redirections. When off, each inserted text is passed as a single argument."), optionsWidget));
+
     // Description
     m_descriptionEdit = new QLineEdit(optionsWidget);
     m_descriptionEdit->setClearButtonEnabled(true);
@@ -129,7 +138,7 @@ EditCommandDialog::EditCommandDialog(const ClipCommand &command, QWidget *parent
     mainLayout->addWidget(buttons);

     create();
-    windowHandle()->resize(560, 440); // default, if there is no saved size
+    windowHandle()->resize(560, 520); // default, if there is no saved size
     KConfigGroup oldGrp = KSharedConfig::openConfig()->group(u"EditCommandDialog"_s);
     KConfigGroup grp = KSharedConfig::openStateConfig()->group(u"klipper"_s).group(u"EditCommandDialog"_s);
     oldGrp.moveValuesTo(grp);
@@ -148,6 +157,7 @@ void EditCommandDialog::updateWidgets()
 {
     m_commandEdit->setText(m_command.command);
     m_descriptionEdit->setText(m_command.description);
+    m_shellCheck->setChecked(m_command.useShell);

     m_replaceRadio->setChecked(m_command.output == ClipCommand::REPLACE);
     m_appendRadio->setChecked(m_command.output == ClipCommand::ADD);
@@ -162,6 +172,7 @@ void EditCommandDialog::saveCommand()
 {
     m_command.command = m_commandEdit->text();
     m_command.description = m_descriptionEdit->text();
+    m_command.useShell = m_shellCheck->isChecked();

     if (m_replaceRadio->isChecked()) {
         m_command.output = ClipCommand::REPLACE;
