+        command.useShell = _cg.readEntry("UseShell", true);
+        addCommand(command);
     }
 }

@@ -431,6 +433,7 @@ void ClipAction::save(KSharedConfigPtr kc, const QString &group) const
         cg.writeEntry("Enabled", cmd.isEnabled);
         cg.writeEntry("Icon", cmd.icon);
         cg.writeEntry("Output", static_cast<int>(cmd.output));
+        cg.writeEntry("UseShell", cmd.useShell);

         ++i;
     }
diff --git a/klipper/urlgrabber.h b/klipper/urlgrabber.h
index 3f4a59b726..8c49800156 100644
--- a/klipper/urlgrabber.h
+++ b/klipper/urlgrabber.h
@@ -131,6 +131,8 @@ struct ClipCommand {
     bool isEnabled;
     QString icon;
